INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2011, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n1.《花的学校》是一首节选自（　　）的儿童散文诗集《（　　）》，他曾获得（　　），出版过《（　　）》《（　　）》。\n2. 这篇散文诗描绘了一群（　　）的花孩子，作者通过（　　），把孩子和妈妈之间的感情表现得自然深厚。", "options": null}', '1. 泰戈尔；《新月集》；诺贝尔文学奖；《飞鸟集》；《吉檀迦利》
