INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2013, '语文', '三年级', '填空', 2, '{"stem": "古诗默写并填空。\n1.《望洞庭》是（　　）代诗人（　　）所作，描写了秋夜皎洁明月下洞庭湖的美丽景象，表达了诗人对洞庭湖的（　　）和（　　）之情。\n2.《山行》是（　　）代诗人（　　）所作，描写和赞美了深秋山林的美丽景色，表达了诗人对（　　）的（　　）之情。\n3.《夜书所见》是（　　）代诗人（　　）所作，通过对秋夜景物的描写，抒发了诗人客居他乡的（　　）和（　　）之情。", "options": null}', '1. 唐；刘禹锡；喜爱；赞美
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2014, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《铺满金色巴掌的水泥道》是（　　）写的一篇散文，本文描写了“我”在上学路上看到的风景，以儿童的视角观察身边的景物，发现平常生活之美，将落叶想象成“（　　）”，充满童真童趣，饱含着（　　）之情。", "options": null}', '张秋生；金色的小巴掌；对生活的热爱', '作者张秋生，课文把法国梧桐树的落叶比作“金色的小巴掌”。', 'paper', '["根据课文填空", "课文5", "第二单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2015, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n秋天的雨，有一盒（　　）的颜料。它把黄色给了（　　），红红的枫叶像一枚枚（　　）。秋天的雨，藏着非常好闻的（　　），梨香香的，菠萝甜甜的。秋天的雨，吹起了（　　），小动物们准备过冬了。", "options": null}', '五彩缤纷；银杏树；邮票；气味；小喇叭', '课文以“雨”为线索，从颜料（颜色）、气味（味道）、声音（小喇叭）三方面描写秋天。', 'paper', '["根据课文填空", "课文6", "第二单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2016, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n秋的声音，在（　　）里，在（　　）里，在（　　）里。秋天的声音是大自然的（　　），我们从秋天的声音中听到了（　　）。", "options": null}', '每一片叶子；每一朵小花；每一滴汗水；交响曲；丰收的喜悦', '诗歌通过对秋天各种声音的描绘，展现秋天的美好和丰收的喜悦。', 'paper', '["根据课文填空", "课文7", "第二单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2017, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《总也倒不了的老屋》讲述了老屋准备倒下时，先后来了（　　）、（　　）和（　　），老屋都满足了他们的请求，体现了老屋（　　）的品质。", "options": null}', '小猫；老母鸡；小蜘蛛；善良、慈爱、乐于助人', '童话故事，老屋虽然破旧但始终不倒，因为不断有小动物来寻求帮助。', 'paper', '["根据课文填空", "课文8", "第三单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2018, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《犟龟》讲述了一只名叫（　　）的乌龟去参加狮王（　　）世婚礼的故事。它在路上先后遇到多种动物的劝阻，但它坚持到达目的地，体现了（　　）的精神。", "options": null}', '陶陶；二十八；坚持不懈、认准目标就不放弃', '德国作家米切尔·恩德的童话。“犟”指固执、坚持，陶陶不顾劝阻坚持到达。', 'paper', '["根据课文填空", "课文9", "第三单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2019, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《小狗学叫》讲述了一只不会叫的狗先后跟（　　）和（　　）学叫，但都不成功。这个故事告诉我们（　　）。", "options": null}', '小公鸡；杜鹃；每个人要找到属于自己的声音，不要盲目模仿别人', '课文通过小狗学叫的经历，告诉我们不要盲目模仿他人。', 'paper', '["根据课文填空", "课文10", "第三单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2020, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《宝葫芦的秘密》是（　　）写的一篇童话故事。故事中奶奶给王葆讲了（　　）的故事，王葆也很想有一个宝葫芦。这个故事告诉我们要靠（　　）获得幸福，不能依靠不劳而获。", "options": null}', '张天翼；宝葫芦；自己的努力', '张天翼（1906-1985），中国现代作家。《宝葫芦的秘密》是中国现代童话经典。', 'paper', '["根据课文填空", "课文11", "第三单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2021, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《在牛肚子里旅行》讲述了（　　）和（　　）两只小蟋蟀的故事。红头被牛吃进肚子里，青头利用牛有（　　）个胃的知识，帮助红头从牛肚子里逃了出来。这告诉我们遇到困难要（　　）。", "options": null}', '红头；青头；四；冷静思考、想办法解决', '牛有四个胃：瘤胃、网胃、瓣胃、皱胃。红头在牛肚子里经过这些胃，最后被反刍出来。', 'paper', '["根据课文填空", "课文12", "第四单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2022, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《一块奶酪》讲述了蚂蚁队长在搬运奶酪时，奶酪掉了一小块。蚂蚁队长先是（　　），后来（　　），让年龄最小的蚂蚁吃掉了那块奶酪。这个故事赞扬了蚂蚁队长（　　）的品质。", "options": null}', '想吃掉那块奶酪；忍住诱惑把它分给最小的蚂蚁；以身作则、关爱弱小、严于律己', '蚂蚁队长面对诱惑最终选择分享，体现自律和关爱。', 'paper', '["根据课文填空", "课文13", "第四单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2023, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《搭船的鸟》通过对翠鸟的观察，写了翠鸟的（　　）和（　　）两个方面。翠鸟捕鱼时（　　），动作非常敏捷。这篇课文告诉我们观察事物要（　　）。", "options": null}', '外貌（外形）；动作（捕鱼）；冲入水中；仔细、按顺序', '课文从用耳朵听和用眼睛看两个方面观察翠鸟，重点描写翠鸟捕鱼的动作。', 'paper', '["根据课文填空", "课文14", "第四单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2024, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《金色的草地》讲述了作者发现草地颜色变化的原因：蒲公英的花在（　　）时金色，在（　　）时绿色。作者通过观察发现了大自然的奥秘，表达了对大自然的（　　）之情。", "options": null}', '早晨（花瓣张开）；傍晚（花瓣合拢）；热爱', '蒲公英花瓣白天张开露出金色，傍晚合拢露出绿色，草地随之变色。', 'paper', '["根据课文填空", "课文15", "第四单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2025, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《富饶的西沙群岛》从（　　）、（　　）、（　　）三个方面介绍了西沙群岛的富饶。西沙群岛是个（　　）的可爱的地方，抒发了作者对它的（　　）之情。", "options": null}', '海面；海底；海岛（鸟粪）；风景优美、物产丰富；喜爱和赞美', '课文从海面（海水）、海底（珊瑚/鱼/海参）、海岛（鸟/鸟蛋/鸟粪）三方面写西沙群岛。', 'paper', '["根据课文填空", "课文16", "第五单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2026, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《海滨小城》从（　　）、（　　）、（　　）、（　　）、（　　）五个场景描写了海滨小城的美丽和整洁。课文围绕“（　　）”这个中心句展开描写。", "options": null}', '大海；沙滩；庭院；公园；街道；这座海滨小城真是又美丽又整洁', '课文按地点转换顺序：大海→沙滩→庭院→公园→街道。中心句在文末总结。', 'paper', '["根据课文填空", "课文17", "第五单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2027, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《美丽的小兴安岭》按照（　　）顺序描写了小兴安岭一年四季的美丽景色。作者把森林比作（　　），把小兴安岭比作（　　），表达了作者对祖国大好河山的（　　）之情。", "options": null}', '四季（春夏秋冬）；绿色的海洋；美丽的大花园；热爱和赞美', '课文按春→夏→秋→冬顺序描写。森林=绿色海洋，小兴安岭=美丽的大花园。', 'paper', '["根据课文填空", "课文18", "第五单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2028, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《香港，璀璨的明珠》从（　　）、（　　）、（　　）三个方面介绍了香港的美丽和繁华，表达了作者对祖国的（　　）之情。", "options": null}', '万国市场；美食天堂；旅游胜地?→实际课文为：港口/贸易、美食、旅游;热爱和赞美', '香港是国际贸易中心、航运中心，也是美食天堂和旅游胜地。', 'paper', '["根据课文填空", "课文19", "第五单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2029, '语文', '三年级', '填空', 2, '{"stem": "古诗默写并填空。\n1.《鹿柴》是（　　）代诗人（　　）所作，描绘了空山深林的幽静景色。\n2.《望天门山》是（　　）代诗人（　　）所作，描写了天门山的壮丽景色。\n3.《饮湖上初晴后雨》是（　　）代诗人（　　）所作，描写了西湖晴天和雨天的不同美景。", "options": null}', '1. 唐；王维
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2030, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《大自然的声音》从（　　）、（　　）、（　　）三个方面描写了大自然的声音之美。微风拂过与狂风吹起的声音不同，水也是大自然的（　　），小雨滴敲敲打打，一场（　　）开始了。", "options": null}', '风；水；动物?→实际课文为风、水、动物三类;音乐家；音乐会', '课文用拟人手法，把风、水、小雨滴比作音乐家，描绘大自然的声音交响曲。', 'paper', '["根据课文填空", "课文21", "第六单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2031, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《读不完的大书》中，作者说大自然是一本读不完的“大书”，书中有（　　）、（　　）、（　　）等好玩的东西。这篇课文告诉我们大自然蕴含着无穷的（　　），表达了作者对大自然的（　　）之情。", "options": null}', '各种小动物；花草树木；风云雨雪?→实际课文写到：小麻雀/老鹰/蚂蚁/花草树木等;奥秘和乐趣；热爱', '作者把大自然比作一本读不完的书，从动物、植物、自然现象中发现无穷乐趣。', 'paper', '["根据课文填空", "课文22", "第六单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2032, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n1.《司马光》是一篇（　　）文，讲述了司马光小时候（　　）的故事。\n2. 文中“群儿戏于庭，一儿登瓮，足跌没水中”，意思是：一群小孩在（　　）玩耍，一个小孩爬到（　　）上，失足跌入（　　）中。\n3.“众皆弃去，光持石击瓮破之，水迸，儿得活”，意思是：其他孩子都（　　），司马光（　　），水（　　），小孩得救了。这个故事赞颂了司马光（　　）的优秀品质。", "options": null}', '1. 文言；砸缸救人
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2033, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《一定要争气》讲述了（　　）小时候（　　）的故事。他在（　　）留学时，决心为中国人争气，经过刻苦努力完成了（　　）实验，表现了他（　　）的精神。", "options": null}', '童第周；刻苦学习、为祖国争气；比利时；青蛙卵剥离;勤奋好学、不甘落后、爱国', '童第周（1902-1979），中国实验胚胎学创始人。在比利时留学时完成了青蛙卵剥离手术实验。', 'paper', '["根据课文填空", "课文24", "第七单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2034, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《手术台就是阵地》讲述了（　　）在（　　）战争中，在炮火中坚持为伤员做手术的故事。课文中说“手术台就是（　　）”，把（　　）比作（　　），突出了白求恩把自己当作战士、对工作（　　）的品质。", "options": null}', '白求恩；抗日战争；阵地；手术台；阵地；极端负责、无私奉献', '诺尔曼·白求恩（1890-1939），加拿大医生，抗日战争期间来华支援中国。课文取自他在前线手术的故事。', 'paper', '["根据课文填空", "课文25", "第七单元"]', NULL, 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2035, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容填空。\n《一个粗瓷大碗》围绕赵一曼烈士的一个粗瓷大碗讲述了感人的故事。赵一曼把碗用来给战士们（　　），自己却饿着肚子。这个故事表现了赵一曼（　　）的品质。", "options": null}', '盛饭?→实际课文为：把仅有的高粱米饭分给战士们;关心战士胜过关心自己、舍己为人', '赵一曼（1905-1936），抗日英雄。粗瓷大碗是她关心战士、舍己为人的象征。', 'paper', '["根据课文填空", "课文26", "第八单元"]', NULL, 0, 1);